package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MaxIterationsExceededException;
import org.apache.commons.math.exception.NumberConvergenceException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BisectionSolver.solve(UnivariateRealFunction, double, double, double)
 */
public class BisectionSolver_solve_TriageGen3Test {

    private BisectionSolver solver;

    @Before
    public void setUp() {
        solver = new BisectionSolver();
    }

    /**
     * Tests the successful execution of the solve method.
     * Note: Based on the provided code snippet, the method calls solve(min, max),
     * which likely ignores 'f' and 'initial' in favor of internal state or a different signature.
     * However, we follow the logic provided: return solve(min, max).
     */
    @Test
    public void testSolve_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x - 2. Root is at 2.0
        UnivariateRealFunction f = x -> x - 2.0;
        double min = 0.0;
        double max = 4.0;
        double initial = 1.0;

        // The implementation provided in the prompt: return solve(min, max);
        // This suggests the solver uses the function passed to the constructor or 
        // the implementation provided is a proxy. 
        // Since the constructor BisectionSolver() is available, we use it.

        // Re-instantiating with a function to ensure solve(min, max) has a function to work with
        solver = new BisectionSolver(f);
        double result = solver.solve(f, min, max, initial);

        // Bisection method should find the root 2.0
        assertEquals(2.0, result, 1e-10);
    }

    /**
     * Tests behavior when the function cannot converge (MaxIterationsExceededException).
     * Note: To trigger this, we need a function that doesn't allow convergence 
     * or an extremely tight tolerance.
     */
    @Test(expected = MaxIterationsExceededException.class)
    public void testSolve_MaxIterationsExceeded() throws MaxIterationsExceededException, FunctionEvaluationException {
        // A function that stays constant or doesn't cross zero in a way that converges
        // Or simply a function that causes the algorithm to fail to meet precision
        UnivariateRealFunction f = x -> 1.0; 
        solver = new BisectionSolver(f);

        // This should trigger an exception because f(min) and f(max) have the same sign
        // or the root is never found.
        solver.solve(f, 0.0, 1.0, 0.5);
    }

    /**
     * Tests behavior when function evaluation fails.
     */
    @Test(expected = FunctionEvaluationException.class)
    public void testSolve_FunctionEvaluationException() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Evaluation failed"));
        };
        solver = new BisectionSolver(f);

        solver.solve(f, 0.0, 2.0, 1.0);
    }

    /**
     * Tests the branch where the provided code calls solve(min, max).
     * This test specifically targets the provided method implementation.
     */
    @Test
    public void testSolve_ImplementationLogic() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Given the provided code: 
        // public double solve(final UnivariateRealFunction f, double min, double max, double initial) {
        //    return solve(min, max);
        // }

        UnivariateRealFunction f = x -> x - 1.0;
        solver = new BisectionSolver(f);

        // We call the 4-parameter version. 
        // It should return the same result as the 2-parameter version.
        double resultWithFourParams = solver.solve(f, 0.0, 2.0, 0.5);
        double resultWithTwoParams = solver.solve(0.0, 2.0);

        assertEquals(resultWithTwoParams, resultWithFourParams, 1e-15);
        assertEquals(1.0, resultWithFourParams, 1e-10);
    }
}
